window.mountExercise = (moduleId, host) => {
'use strict';
const modules = window.learningModules.filter(m=>m.id===moduleId);
if(!modules.length)throw new Error('Unknown module');
document.querySelector('.model-dialog')?.remove();
host.classList.add('learning-deck');
const {sameSolvedFormula, unit, molecularDipole, atomCounts, validCoefficients} = window.learningMath;
const $ = (s,root=document) => root.querySelector(s);
const $$ = (s,root=document) => [...root.querySelectorAll(s)];
const escape = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const option = (v,label=v) => `<option value="${escape(v)}">${escape(label)}</option>`;
const fieldNames = {left:'Operation i vänsterled',right:'Operation i högerled',objects:'Objekt som påverkar föremålet',force0:'Tyngdkraftens riktning',force1:'Normalkraftens riktning',force2:'Motståndskraftens riktning',force3:'Dragkraftens riktning',kind:'Bildtyp',orientation:'Bildens riktning',size:'Bildens storlek',geometry:'Molekylform',angle:'Bindningsvinkel',polar:'Polaritet',category:'Ordklass'};
const select = (name,values) => `<select data-field="${name}" aria-label="${fieldNames[name]||name}">${option('','Välj…')}${values.map(v=>option(v)).join('')}</select>`;
const states = modules.map(()=>({level:1,variant:0,attempt:false,solved:false,choice:null,word:null,step:0,order:[],angleX:.3,angleY:.4}));
const slides=host;
slides.innerHTML=modules.map((m,i)=>`<section class="slide" data-module="${i}"><p>${m.instruction}</p><div class="module-toolbar"><label>Stödnivå <select data-level>${option(1,'1 · Stöttad')}${option(2,'2 · Delvis stöttad')}${option(3,'3 · Självständig')}</select></label><span data-variant></span><button data-new>Nästa uppgift</button></div><div class="exercise-layout"><div class="task"><div data-question class="question"></div><div data-inputs></div><div class="actions"><button class="primary" data-check>Kontrollera svar</button><button data-clear>Börja om uppgiften</button></div><div class="feedback" data-feedback role="status" aria-live="polite"></div></div><div><div data-support></div><div class="visual" data-visual></div><button data-enlarge>Förstora modellen</button><p class="mini-note" data-no-visual hidden>Utan visuellt stöd: gör ett eget försök. Modellen visas efter kontrollen.</p></div></div></section>`).join('')+'<section class="recall-section"><h2>Vad minns du?</h2><p>Pröva utan modellen när du är klar med uppgifterna.</p><div id="recall"></div></section>';
const dialog=document.createElement('dialog');
dialog.className='model-dialog';dialog.setAttribute('aria-label','Förstorad modell');
dialog.innerHTML='<button data-close-model>Stäng modellen</button><div data-model-slot></div>';
document.body.append(dialog);
let modelOrigin=null;
$('[data-close-model]',dialog).onclick=()=>dialog.close();
dialog.addEventListener('close',()=>{if(modelOrigin){modelOrigin.button.before($('[data-model-slot]',dialog).firstElementChild);modelOrigin.button.focus();modelOrigin=null;}});
$$('[data-enlarge]').forEach(button=>button.onclick=()=>{modelOrigin={button};$('[data-model-slot]',dialog).append($('[data-visual]',button.parentElement));dialog.showModal();});
const rootFor=i=>$(`[data-module="${i}"]`);
function feedback(i,ok,text){const el=$('[data-feedback]',rootFor(i));el.dataset.status=ok?'correct':'retry';el.textContent=(ok?'Rätt. ':'')+text;}
function answerChanged(i){const s=states[i];if(s.attempt){s.solved=false;feedback(i,false,'Svaret har ändrats. Kontrollera det igen.');}}
function values(i){return Object.fromEntries($$('[data-field]',rootFor(i)).map(el=>[el.dataset.field,el.value]));}
function choices(options,name='choice'){return `<div class="choices" role="group" aria-label="Svarsalternativ">${options.map((t,i)=>`<button data-${name}="${i}" aria-pressed="false">${escape(t)}</button>`).join('')}</div>`;}
function svg(content,label){return `<svg viewBox="0 0 580 360" role="img" aria-label="${escape(label)}"><defs><marker id="arrow-${label.replace(/\W/g,'')}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="context-stroke"/></marker></defs>${content}</svg>`;}
const line=(x1,y1,x2,y2,color='#2457a6',width=3,dash='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="${width}" ${dash?'stroke-dasharray="6 5"':''}/>`;
function arrow(x1,y1,x2,y2,color='#2457a6',label=''){const a=Math.atan2(y2-y1,x2-x1),size=Math.min(10,Math.hypot(x2-x1,y2-y1)*.5);return line(x1,y1,x2,y2,color)+`<path d="M${x2-size*Math.cos(a-.45)} ${y2-size*Math.sin(a-.45)}L${x2} ${y2}L${x2-size*Math.cos(a+.45)} ${y2-size*Math.sin(a+.45)}" fill="none" stroke="${color}" stroke-width="3"/>`+(label?`<text x="${x2+10}" y="${y2-8}">${label}</text>`:'');}
const txt=(x,y,t)=>`<text x="${x}" y="${y}">${escape(t)}</text>`;
function drawGraph(k,m,old){let c='';for(let n=-5;n<=5;n++){const p=290+n*27;c+=line(p,32,p,302,'#e1e2e4',1);c+=line(155,167-n*27,425,167-n*27,'#e1e2e4',1);if(n)c+=txt(p-5,326,n)+txt(120,172-n*27,n);}c+=line(155,167,440,167,'#777',1.5)+line(290,310,290,18,'#777',1.5)+txt(447,172,'x')+txt(297,20,'y');const path=(a,b,color,dash='')=>{let pts=[];for(let x=-5;x<=5;x+=.025){const y=a*x+b;if(y>=-5&&y<=5)pts.push(`${290+x*27},${167-y*27}`);}return `<polyline points="${pts.join(' ')}" fill="none" stroke="${color}" stroke-width="3" ${dash?'stroke-dasharray="6 5"':''}/>`;};if(old)c+=path(old.k,old.m,'#9b9b9b',true);c+=path(k,m,'#2457a6')+`<circle cx="290" cy="${167-m*27}" r="5" fill="#2457a6"/>`;return svg(c,`Graf y = ${k}x + ${m}`);}
function drawForce(t,v){let c=t.scene==='fall'?`<circle cx="290" cy="180" r="23" fill="#d9e7f5" stroke="#2457a6"/>`:`<rect x="250" y="150" width="80" height="60" fill="#d9e7f5" stroke="#2457a6"/>${line(100,215,480,215,'#888',3)}`;const names=['Tyngd','Normal','Friktion/luft','Drag'],dirs={Uppåt:[0,-1],Nedåt:[0,1],Vänster:[-1,0],Höger:[1,0]};names.forEach((n,j)=>{const d=dirs[v['force'+j]];if(d){const mag=Number(v['size'+j]);if(!Number.isFinite(mag)||mag<5||mag>60)return;c+=arrow(290,180,290+d[0]*(mag*1.5),180+d[1]*(mag*1.5),['#9c4221','#2457a6','#77549b','#287b53'][j],n);}});return svg(c,'Elevens kraftdiagram')+'<p class="visual-caption">Punktmodell: krafterna flyttas till föremålets centrum. Pilarna visar ditt svar; rotation behandlas inte.</p>';}
function drawOptics(t,reveal){const X=x=>290+x*6,Y=y=>180-y*6,h=8;let c=line(30,180,550,180,'#aaa',1)+line(290,25,290,335,'#2457a6',4)+txt(299,28,'Lins')+arrow(X(-t.a),180,X(-t.a),Y(h),'#287b53','Föremål');[-t.f,t.f].forEach(f=>c+=`<circle cx="${X(f)}" cy="180" r="4" fill="#171717"/>`+txt(X(f)-8,204,'F'));c+=txt(20,344,'Avstånd i cm · schematisk tunn lins');if(reveal){const b=t.b,ih=-b/t.a*h; c+=arrow(X(b),180,X(b),Y(ih),'#9c4221','Bild');c+=line(X(-t.a),Y(h),290,Y(h),'#2457a6')+line(290,Y(h),X(40),Y(h-40*h/t.f),'#2457a6');c+=line(X(-t.a),Y(h),290,180,'#ad6a2c')+line(290,180,X(40),Y(-40*h/t.a),'#ad6a2c');if(b<0)c+=line(X(b),Y(ih),290,Y(h),'#2457a6',2,true)+line(X(b),Y(ih),290,180,'#ad6a2c',2,true);c+=txt(25,28,`b = ${b} cm; förstoring = ${(-b/t.a).toFixed(1)}`);}return svg(c,'Samlingslins och huvudstrålar')+'<p class="visual-caption">Blå: parallellstråle genom F. Brun: genom linscentrum. Streckat: bakåtförlängningar. Strålar utanför bildytan är beskurna.</p>';}
function molecule(t,s){const project=p=>{let [x,y,z]=p;const xx=x*Math.cos(s.angleY)+z*Math.sin(s.angleY),zz=-x*Math.sin(s.angleY)+z*Math.cos(s.angleY);return [290+xx*112,170+(y*Math.cos(s.angleX)-zz*Math.sin(s.angleX))*112,y*Math.sin(s.angleX)+zz*Math.cos(s.angleX)];};const pts=t.points.map(unit).map(project);let c='';pts.forEach(p=>c+=line(290,170,p[0],p[1],'#999',9));const palette={H:'#e3eaf0',C:'#596675',N:'#477ae0',O:'#df504e',B:'#d4a46e',F:'#74bd72',S:'#dac04b'};let gradients='';Object.entries(palette).forEach(([atom,color])=>gradients+=`<radialGradient id="atom-${atom}" cx="30%" cy="25%" r="75%"><stop offset="0%" stop-color="#ffffff"/><stop offset="45%" stop-color="${color}"/><stop offset="100%" stop-color="#233447"/></radialGradient>`);c+=`<defs>${gradients}</defs>`;const atoms=[...pts.map(p=>({p,label:t.outer})),{p:[290,170,0],label:t.center}].sort((a,b)=>a.p[2]-b.p[2]);atoms.forEach(({p,label})=>c+=`<circle cx="${p[0]}" cy="${p[1]}" r="${21+p[2]*2}" fill="url(#atom-${label})" stroke="#777"/>`+`<text x="${p[0]}" y="${p[1]+5}" text-anchor="middle" style="font-weight:700;fill:#101e29;paint-order:stroke;stroke:#fff;stroke-width:2px">${label}</text>`);if(s.attempt){pts.forEach(p=>{let a=[290+(p[0]-290)*.27,170+(p[1]-170)*.27],b=[290+(p[0]-290)*.7,170+(p[1]-170)*.7];if(t.towardCenter)[a,b]=[b,a];c+=arrow(...a,...b,'#77549b');});if(t.polar==='Polär'){const p=project(molecularDipole(t));c+=arrow(290,170,p[0],p[1],'#287b53','Netto');}c+=txt(20,335,t.polar==='Opolär'?'Nettodipol = 0':`${t.polar} · nettodipolen visas i grönt`);}return svg(c,`Roterbar modell av ${t.name}`)+`<p class="visual-caption">${s.attempt?'Lila pilar: bindningsdipoler mot högre elektronegativitet. Grönt: deras vektorsumma. Längder jämförs inom samma molekyl, inte mellan ämnen. ':''}Dra för att rotera i 3D, eller använd reglagen. Schematisk modell; atomstorlekar och bindningslängder är inte skalenliga.</p>`;}
function particleModel(t,coeff){let c='';const colors={H:'#d9e7f5',O:'#f0c6bd',C:'#b7b7b7',Al:'#e5dbb1',Fe:'#dfbc99'};[0,1].forEach(side=>{c+=txt(side?315:15,25,side?'Produkter':'Reaktanter');let row=0;t.atoms.forEach((atoms,j)=>{if((j<t.split?0:1)!==side)return;c+=txt(side?315:15,52+row*96,`${coeff[j]} ${t.labels[j]}`);for(let n=0;n<coeff[j];n++){let pos=0;Object.entries(atoms).forEach(([e,count])=>{for(let a=0;a<count;a++){const x=(side?328:28)+n*38+(pos%2)*13,y=72+row*96+Math.floor(pos/2)*20;c+=`<circle cx="${x}" cy="${y}" r="10" fill="${colors[e]||'#ddd'}" stroke="#888"/>`+`<text x="${x-5}" y="${y+4}" style="font-size:11px">${e}</text>`;pos++;}});}row++;});});return svg(c,'Partikelräkning på båda sidor')+'<p class="visual-caption">Grupperna visar formelenheternas atomer, inte deras geometri. Jonföreningar består inte av enskilda molekyler.</p>';}
function renderVisual(i){const m=modules[i],s=states[i],t=m.tasks[s.variant],r=rootFor(i),v=values(i),el=$('[data-visual]',r);el.hidden=s.level===3&&!s.attempt;$('[data-no-visual]',r).hidden=!el.hidden;$('[data-enlarge]',r).hidden=el.hidden;if(el.hidden)return;
if(m.type==='formula'){el.innerHTML=svg(`<rect x="35" y="110" width="225" height="90" rx="5" fill="#edf3fb" stroke="#b8c9df"/><rect x="320" y="110" width="225" height="90" rx="5" fill="#edf3fb" stroke="#b8c9df"/>${txt(65,160,t.left)}${txt(350,160,t.right)}${txt(282,160,'=')}${txt(50,238,'Vänsterled')}${txt(345,238,'Högerled')}${s.attempt?txt(40,295,s.solved?t.result:'Samma operation krävs på båda sidor.'):txt(40,295,'Likheten ska bevaras i varje steg.')}`,'Likhet mellan två led');}
if(m.type==='graph'){const k=s.attempt?Number(v.k??t.nextK):t.k,mm=s.attempt?Number(v.m??t.nextM):t.m;el.innerHTML=drawGraph(k,mm,s.attempt?{k:t.k,m:t.m}:null)+`<p class="visual-caption">${s.attempt?'Blå: ny linje. Streckad: ursprunglig linje.':'Ursprunglig linje; förutsäg innan den ändras.'} y = ${k}x ${mm<0?'−':'+'} ${Math.abs(mm)}</p>`;}
if(m.type==='forces')el.innerHTML=drawForce(t,v);
if(m.type==='optics')el.innerHTML=drawOptics(t,s.attempt);
if(m.type==='molecules'){el.innerHTML=`<div class="molecule-view">${molecule(t,s)}</div><div class="inline-controls"><label>Rotation i sidled <input data-rotate="y" type="range" min="-180" max="180" value="${s.angleY*180/Math.PI}" aria-label="Rotera molekylen i sidled"></label><label>Rotation i höjdled <input data-rotate="x" type="range" min="-180" max="180" value="${s.angleX*180/Math.PI}" aria-label="Rotera molekylen i höjdled"></label></div>`;const redraw=()=>{$('.molecule-view',el).innerHTML=molecule(t,s);};$$('[data-rotate]',el).forEach(input=>input.oninput=()=>{s[input.dataset.rotate==='y'?'angleY':'angleX']=Number(input.value)*Math.PI/180;redraw();});const view=$('.molecule-view',el);let drag=null;view.onpointerdown=e=>{drag=[e.clientX,e.clientY];view.setPointerCapture(e.pointerId);};view.onpointermove=e=>{if(!drag)return;s.angleY+=(e.clientX-drag[0])*.012;s.angleX-=(e.clientY-drag[1])*.012;drag=[e.clientX,e.clientY];redraw();$$('[data-rotate]',el).forEach(input=>input.value=s[input.dataset.rotate==='y'?'angleY':'angleX']*180/Math.PI);};view.onpointerup=view.onpointercancel=()=>drag=null;}
if(m.type==='balance'){if(!s.attempt){el.innerHTML='<p>Vilka atomer finns på varje sida?</p><p>Partikelmodellen och atomräkningen visas när du har lämnat ett svar.</p>';return;}const coeff=t.labels.map((_,j)=>Number(v['coef'+j]));if(!validCoefficients(coeff)){el.innerHTML='<p>Ange heltalskoefficienter 1–6 för att visa atomräkningen.</p>';return;}const rows=atomCounts(t,coeff);el.innerHTML=particleModel(t,coeff)+`<table><caption>Atomantal i ditt svar</caption><thead><tr><th>Grundämne</th><th>Vänster</th><th>Höger</th></tr></thead><tbody>${rows.map(a=>`<tr><th>${a.e}</th><td>${a.left}</td><td>${a.right} ${a.left===a.right?'✓':'≠'}</td></tr>`).join('')}</tbody></table>`;}
if(m.type==='words')el.innerHTML=`<p class="visual-caption">Samma ordform kan ha olika funktioner.</p><p>${m.subject==='Svenska'?'Ett <strong>högt</strong> ljud. → beskriver ett substantiv.<br>Hon sjunger <strong>högt</strong>. → beskriver ett verb.':'A <strong>hard</strong> task. → modifies a noun.<br>She works <strong>hard</strong>. → modifies a verb.'}</p>${s.attempt?`<p>${escape(t.why)}</p>`:''}`;
if(m.type==='sentence')el.innerHTML=`<p>Analysordning</p><ol><li>Predikat – vad händer?</li><li>Subjekt – vem/vad gör det?</li><li>Objekt – vad/vem påverkas?</li><li>Adverbial – när, var, hur, varför?</li></ol><p class="visual-caption">Ordklass beskriver ordtypen. Satsdel beskriver ordets eller frasens uppgift i satsen.</p>`;
if(m.type==='wordorder')el.innerHTML=`<p>Fråga med frågeord</p><p>Frågeord → hjälpverb → subjekt → adverb → huvudverb</p><p class="visual-caption">Frågeord → hjälpverb → subjekt → frekvensadverb → huvudverb.</p><p>Exempel: Does Mia play tennis?<br>Påstående: Mia plays tennis.</p>`;
}
function renderModule(i){const m=modules[i],s=states[i],t=m.tasks[s.variant],r=rootFor(i);$('[data-level]',r).value=s.level;$('[data-variant]',r).textContent=`Variant ${s.variant+1}/${m.tasks.length}`;$('[data-support]',r).innerHTML=s.level===3?'':`<details class="example" ${s.level===1?'open':''}><summary>Genomgånget exempel</summary><p>${escape(m.example)}</p></details>${s.level===1?`<p class="hint">${escape(m.hint)}</p>`:`<details><summary>Ledtråd</summary><p>${escape(m.hint)}</p></details>`}`;$('[data-feedback]',r).textContent='';$('[data-question]',r).textContent=t.q||(m.type==='molecules'?`${t.name}: vilken form, vinkel och polaritet? ${t.lewis}`:m.type==='balance'?'Balansera reaktionen med minsta positiva heltal.':m.type==='sentence'?'Börja med att markera predikatet.':`Markera ”${t.sentence[t.target].replace(/[.!?]$/,'')}” och välj ordklass.`);
let html='';
if(m.type==='formula')html=s.level===3?`<label>Skriv den omvandlade formeln <input type="text" data-field="formula" style="width:16rem" placeholder="variabel = uttryck" maxlength="200" autocomplete="off"></label>`:`<div class="equation"><span>${escape(t.left)}</span><span>=</span><span>${escape(t.right)}</span></div><div class="inline-controls"><label>Vänsterled ${select('left',t.ops)}</label><label>Högerled ${select('right',t.ops)}</label></div>`;
if(m.type==='graph')html=choices(t.options)+`<fieldset data-sliders disabled><legend>Undersök efter ditt svar</legend><label>k <input data-field="k" type="range" min="-3" max="3" step=".5" value="${t.nextK}"><output data-k>${t.nextK}</output></label> <label>m <input data-field="m" type="range" min="-3" max="3" step=".5" value="${t.nextM}"><output data-m>${t.nextM}</output></label></fieldset>`;
if(m.type==='forces')html=`<label>Vilka objekt påverkar? ${select('objects',t.objects)}</label><fieldset data-force-fields disabled><legend>Krafter på föremålet</legend><div class="force-controls">${['Tyngdkraft','Normalkraft','Friktion/luftmotstånd','Dragkraft'].map((n,j)=>`<label><span>${n}</span> ${select('force'+j,['Ingen','Uppåt','Nedåt','Vänster','Höger'])}<input data-field="size${j}" type="number" min="5" max="60" step="5" value="20" aria-label="Storlek ${n} i newton"><span>N</span></label>`).join('')}</div></fieldset>`;
if(m.type==='optics')html=`<div class="inline-controls"><label>Bildavstånd b <input data-field="distance" type="number" step="any"> cm</label><label>Bildtyp ${select('kind',['Verklig','Virtuell'])}</label><label>Riktning ${select('orientation',['Rättvänd','Uppochnedvänd'])}</label><label>Storlek ${select('size',['Förstorad','Lika stor','Förminskad'])}</label></div>`;
if(m.type==='molecules')html=`<div class="inline-controls"><label>Molekylform ${select('geometry',['Linjär','Vinklad','Trigonal pyramid','Tetraeder','Trigonal plan','Oktaeder'])}</label><label>Vinkel ${select('angle',['180°','≈ 104,5°','≈ 107°','≈ 109,5°','120°','90° och 180°'])}</label><label>Polaritet ${select('polar',['Polär','Opolär'])}</label></div>`;
if(m.type==='balance')html=`<div class="equation">${t.labels.map((label,j)=>`${j?(j===t.split?' → ':' + '):''}<label><input data-field="coef${j}" type="number" min="1" max="6" step="1" value="1" aria-label="Koefficient för ${label}">${label}</label>`).join('')}</div><p class="mini-note">Koefficienter 1–6 räcker i dessa uppgifter. Indexen är låsta: en ändring skulle byta ämne.</p>`;
if(m.type==='words')html=`<div class="sentence">${t.sentence.map((word,j)=>`<button data-word="${j}" aria-pressed="false">${escape(word)}</button>`).join('')}</div><label>Ordklass ${select('category',s.level===1?m.categories.filter(c=>[t.answer,m.subject==='Svenska'?'Adjektiv':'Adjective',m.subject==='Svenska'?'Adverb':'Adverb'].includes(c)):m.categories)}</label>`;
if(m.type==='sentence')html=`<p data-step>1. Markera predikatet.</p><div class="sentence">${t.parts.map((p,j)=>`<button data-part="${j}">${escape(p)}</button>`).join('')}</div>`;
if(m.type==='wordorder')html='<p class="mini-note">Klicka orden i ordning. Dra ett ord till ett placerat ord för att lägga det före.</p><div class="sentence" data-built aria-label="Din mening"></div><div class="word-bank" data-bank aria-label="Tillgängliga ord"></div>';
$('[data-inputs]',r).innerHTML=html;$('[data-check]',r).hidden=m.type==='sentence';
if(m.type==='formula'&&s.level===1){$('[data-field="left"]',r).value=t.answer;$('[data-field="left"]',r).disabled=true;}
$$('[data-choice]',r).forEach(b=>b.onclick=()=>{answerChanged(i);s.choice=Number(b.dataset.choice);$$('[data-choice]',r).forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});
$$('[data-word]',r).forEach(b=>b.onclick=()=>{answerChanged(i);s.word=Number(b.dataset.word);$$('[data-word]',r).forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});
if(m.type==='forces')$('[data-field="objects"]',r).onchange=e=>{const ok=e.target.value===t.objects[t.objectAnswer];$('[data-force-fields]',r).disabled=!ok;if(e.target.value)feedback(i,false,ok?'Nu kan du sätta ut krafterna.':'Koppla varje kraft till ett annat objekt: kontakt, gravitation eller luft. Välj igen.');};
$$('[data-field]',r).forEach(input=>input.addEventListener('input',()=>{if(m.type!=='graph')answerChanged(i);if(m.type==='graph'){if($('[data-k]',r))$('[data-k]',r).textContent=values(i).k;$('[data-m]',r).textContent=values(i).m;}if(['graph','forces','balance'].includes(m.type))renderVisual(i);}));
if(m.type==='sentence')$$('[data-part]',r).forEach(b=>b.onclick=()=>{if(s.step>=4)return;const n=Number(b.dataset.part),ok=n===t.order[s.step];s.attempt=true;if(ok){const names=['Predikat','Subjekt','Objekt','Adverbial'];b.textContent=`${t.parts[n]} · ${names[s.step]}`;b.disabled=true;feedback(i,true,t.explanations[s.step]);s.step++;$('[data-step]',r).textContent=s.step===4?'Hela satsen är analyserad. Pröva en ny variant.':`${s.step+1}. Markera ${names[s.step].toLowerCase()}.`;s.solved=s.step===4;}else feedback(i,false,['Leta efter verbet som beskriver handlingen.','Vem utför handlingen? Subjektet behöver inte stå först.','Vad är det som läses, förklaras eller hittas?','Vilken fras anger tid, plats eller sätt?'][s.step]);renderVisual(i);});
if(m.type==='wordorder')renderWords(i);
renderVisual(i);
}
function renderWords(i){answerChanged(i);const t=modules[i].tasks[states[i].variant],s=states[i],r=rootFor(i);const button=j=>`<button draggable="true" data-token="${j}">${escape(t.words[j])}</button>`;$('[data-built]',r).innerHTML=s.order.map(button).join('')||'<span class="hint">Din mening…</span>';$('[data-bank]',r).innerHTML=t.words.map((_,j)=>j).filter(j=>!s.order.includes(j)).map(button).join('');$$('[data-token]',r).forEach(b=>{b.onclick=()=>{const j=Number(b.dataset.token);s.order=s.order.includes(j)?s.order.filter(n=>n!==j):[...s.order,j];renderWords(i);};b.ondragstart=e=>e.dataTransfer.setData('text/plain',b.dataset.token);b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();e.stopPropagation();const j=Number(e.dataTransfer.getData('text/plain')),target=Number(b.dataset.token);if(!Number.isInteger(j)||j<0||j>=t.words.length||j===target)return;s.order=s.order.filter(n=>n!==j);const pos=s.order.indexOf(target);s.order.splice(pos<0?s.order.length:pos,0,j);renderWords(i);};});for(const zone of ['[data-built]','[data-bank]']){const el=$(zone,r);el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();const j=Number(e.dataTransfer.getData('text/plain'));if(!Number.isInteger(j)||j<0||j>=t.words.length)return;s.order=s.order.filter(n=>n!==j);if(zone==='[data-built]')s.order.push(j);renderWords(i);};}}
function check(i){const m=modules[i],s=states[i],t=m.tasks[s.variant],v=values(i);let ok=false,message='';
if(m.type==='formula'){if(s.level===3){if(!v.formula.trim())return feedback(i,false,'Skriv en formel först.');ok=sameSolvedFormula(v.formula,t.result);message=ok?t.why:`Bevara likheten genom samma operation på båda sidor. En möjlig form är ${t.result}. Använd samma stora/små bokstäver som i uppgiften, / för division och * för multiplikation. Parenteser stöds. Försök igen.`;}else{if(!v.left||!v.right)return feedback(i,false,'Välj operation för båda leden.');ok=v.left===t.answer&&v.right===t.answer;message=ok?`${t.result}. ${t.why}`:v.left!==v.right?'Du valde olika operationer. Gör samma operation på båda sidor för att bevara likheten.':`Likheten bevaras, men variabeln blir inte ensam. ${t.why} Försök igen.`;}}
if(m.type==='graph'){if(s.choice===null)return feedback(i,false,'Gör en förutsägelse först.');ok=s.choice===t.answer;message=t.why+(ok?' Ändra nu reglagen och jämför.':' Jämför linjerna och välj igen.');$('[data-sliders]',rootFor(i)).disabled=false;$('[data-field="k"]',rootFor(i)).value=t.nextK;$('[data-field="m"]',rootFor(i)).value=t.nextM;$('[data-k]',rootFor(i)).textContent=t.nextK;$('[data-m]',rootFor(i)).textContent=t.nextM;}
if(m.type==='forces'){if(v.objects!==t.objects[t.objectAnswer])return feedback(i,false,'Välj först vilka objekt som faktiskt påverkar föremålet.');if(t.forces.some((_,j)=>!v['force'+j]))return feedback(i,false,'Välj riktning eller Ingen på varje rad.');if(t.forces.some((_,j)=>v['force'+j]!=='Ingen'&&(!Number.isFinite(Number(v['size'+j]))||Number(v['size'+j])<5||Number(v['size'+j])>60)))return feedback(i,false,'Ange storlekar mellan 5 och 60 N för de krafter du har valt.');const dirs=t.forces.every((x,j)=>v['force'+j]===x);const active=t.forces.map((x,j)=>x==='Ingen'?null:j).filter(x=>x!==null);const magnitude=t.scene==='box'?Number(v.size0)===Number(v.size1)&&Number(v.size2)===Number(v.size3):Number(v['size'+active[0]])===Number(v['size'+active[1]]);ok=dirs&&magnitude;message=ok?t.why:!dirs?'Någon kraft saknas eller har fel riktning. Tyngd är nedåt, normalkraft vinkelrät mot ytan och motstånd mot rörelsen. Kontrollera ditt diagram.':'Föremålet accelererar inte. Motsatta krafter måste vara lika stora. Justera storlekarna.';}
if(m.type==='optics'){if(!v.distance||!v.kind||!v.orientation||!v.size)return feedback(i,false,'Fyll i avstånd och alla tre egenskaper först.');ok=Math.abs(Number(v.distance)-t.b)<1e-6&&v.kind===t.kind&&v.orientation===t.orientation&&v.size===t.size;message=`1/b = 1/${t.f} − 1/${t.a} ger b = ${t.b} cm. Bilden är ${t.kind.toLowerCase()}, ${t.orientation.toLowerCase()} och ${t.size.toLowerCase()}. ${ok?'':'Följ huvudstrålarna och korrigera svaret.'}`;}
if(m.type==='molecules'){if(!v.geometry||!v.angle||!v.polar)return feedback(i,false,'Välj form, vinkel och polaritet före kontrollen.');ok=v.geometry===t.geometry&&v.angle===t.angle&&v.polar===t.polar;message=`${t.geometry}, ${t.angle}, ${t.polar.toLowerCase()}. ${t.why}${ok?'':' Rotera modellen och försök igen.'}`;}
if(m.type==='balance'){const coeff=t.labels.map((_,j)=>Number(v['coef'+j]));if(!validCoefficients(coeff))return feedback(i,false,'Använd positiva heltal mellan 1 och 6.');const counts=atomCounts(t,coeff);ok=coeff.every((n,j)=>n===t.answer[j]);const mismatch=counts.find(a=>a.left!==a.right);message=ok?'Samma antal av varje atomslag finns på båda sidor. Koefficienterna är minsta positiva heltal.':mismatch?`${mismatch.e}: ${mismatch.left} atomer till vänster men ${mismatch.right} till höger. Ändra koefficienterna, inte indexen, och försök igen.`:'Atomerna är balanserade, men koefficienterna kan förkortas. Använd minsta positiva heltal.';}
if(m.type==='words'){if(s.word===null||!v.category)return feedback(i,false,'Markera ett ord och välj ordklass.');ok=s.word===t.target&&v.category===t.answer;message=s.word!==t.target?`Uppgiften gäller ordet ”${t.sentence[t.target]}”. Markera det ordet först.`:t.why+(ok?'':` Ordklassen är ${t.answer.toLowerCase()}. Korrigera ditt svar.`);}
if(m.type==='wordorder'){if(s.order.length!==t.words.length)return feedback(i,false,'Använd alla ord och skiljetecknet först.');ok=s.order.map(j=>t.words[j]).join(' ')===t.answer.join(' ');message=ok?t.why:`${t.why} Flytta orden och försök igen.`;}
s.attempt=true;s.solved=ok;feedback(i,ok,message);renderVisual(i);
}
modules.forEach((m,i)=>{const r=rootFor(i);const reset=()=>{const old=states[i];states[i]={level:old.level,variant:old.variant,attempt:false,solved:false,choice:null,word:null,step:0,order:[],angleX:.3,angleY:.4};renderModule(i);};$('[data-level]',r).onchange=e=>{states[i].level=Number(e.target.value);reset();};$('[data-new]',r).onclick=()=>{states[i].variant=(states[i].variant+1)%m.tasks.length;reset();};$('[data-clear]',r).onclick=reset;$('[data-check]',r).onclick=()=>check(i);renderModule(i);});
function renderRecall(){const t=modules[0].recall;$('#recall').innerHTML=`<p class="question">${escape(t.q)}</p>${choices(t.options,'recall-choice')}<div class="feedback" id="recall-feedback" role="status" aria-live="polite"></div>`;$$('[data-recall-choice]').forEach(b=>b.onclick=()=>{const ok=Number(b.dataset.recallChoice)===t.answer;$$('[data-recall-choice]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#recall-feedback').dataset.status=ok?'correct':'retry';$('#recall-feedback').textContent=(ok?'Rätt. ':'Försök igen. ')+t.why;});}
renderRecall();
};
